"use strict";(self.webpackChunkpaulus_seo=self.webpackChunkpaulus_seo||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"website-improvements-part-2","metadata":{"permalink":"/blog/website-improvements-part-2","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-01-18-website-improvements.md","source":"@site/blog/2026-01-18-website-improvements.md","title":"\uc6f9\uc0ac\uc774\ud2b8 \uae30\ub2a5 \uac1c\uc120 \uae30\ub85d (2)","description":"\uc548\ub155\ud558\uc138\uc694! \uc5b4\uc81c\uc5d0 \uc774\uc5b4 \uc624\ub298\ub3c4 \uc6f9\uc0ac\uc774\ud2b8 \uc0ac\uc6a9\uc131 \uac1c\uc120\uc744 \uc704\ud574 \uba87 \uac00\uc9c0 \uc5c5\ub370\uc774\ud2b8\ub97c \uc9c4\ud589\ud588\uc2b5\ub2c8\ub2e4.","date":"2026-01-18T00:00:00.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"web-dev","permalink":"/blog/tags/web-dev"},{"inline":true,"label":"ux","permalink":"/blog/tags/ux"},{"inline":true,"label":"ui","permalink":"/blog/tags/ui"}],"readingTime":1.14,"hasTruncateMarker":true,"authors":[{"name":"Paul Seo","title":"Robotics Software Engineer, Hyundai-WIA","url":"http://linkedin.com/in/paulusseo/","page":{"permalink":"/blog/authors/paulus-seo"},"socials":{"github":"https://github.com/paulus-seo","linkedin":"https://www.linkedin.com/in/paulusseo/"},"imageURL":"https://github.com/paulus-seo.png","key":"paulus-seo"}],"frontMatter":{"slug":"website-improvements-part-2","title":"\uc6f9\uc0ac\uc774\ud2b8 \uae30\ub2a5 \uac1c\uc120 \uae30\ub85d (2)","authors":["paulus-seo"],"tags":["docusaurus","web-dev","ux","ui"]},"unlisted":false,"nextItem":{"title":"\uc6f9\uc0ac\uc774\ud2b8 \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d","permalink":"/blog/website-renewal"}},"content":"\uc548\ub155\ud558\uc138\uc694! \uc5b4\uc81c\uc5d0 \uc774\uc5b4 \uc624\ub298\ub3c4 \uc6f9\uc0ac\uc774\ud2b8 \uc0ac\uc6a9\uc131 \uac1c\uc120\uc744 \uc704\ud574 \uba87 \uac00\uc9c0 \uc5c5\ub370\uc774\ud2b8\ub97c \uc9c4\ud589\ud588\uc2b5\ub2c8\ub2e4.\\n\uc774\ubc88 \uc5c5\ub370\uc774\ud2b8\ub294 \uc8fc\ub85c \ubc29\ubb38\uc790 \uacbd\ud5d8(UX)\uacfc \uc778\ud130\ud398\uc774\uc2a4(UI)\ub97c \uac1c\uc120\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucdc4\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n**\uc8fc\uc694 \uac1c\uc120 \ub0b4\uc6a9:**\\n\\n1.  **\ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ub4dc\ub86d\ub2e4\uc6b4 \uba54\ub274 \uc801\uc6a9**:\\n    \uc0c1\ub2e8 \ub124\ube44\uac8c\uc774\uc158\uc758 `About`, `Projects`, `Awards` \ub9c1\ud06c\ub97c `Portfolio`\ub77c\ub294 \ud558\ub098\uc758 \ub4dc\ub86d\ub2e4\uc6b4 \uba54\ub274\ub85c \ud1b5\ud569\ud588\uc2b5\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 \ub124\ube44\uac8c\uc774\uc158 \ubc14\uac00 \ub354 \uae54\ub054\ud574\uc84c\uace0, \uad00\ub828 \ud398\uc774\uc9c0\ub4e4\uc744 \ub17c\ub9ac\uc801\uc73c\ub85c \uadf8\ub8f9\ud654\ud558\uc5ec \uc811\uadfc\uc131\uc744 \ub192\uc600\uc2b5\ub2c8\ub2e4.\\n\\n2.  **\ud504\ub85c\uc81d\ud2b8 \ud398\uc774\uc9c0 \uce74\ub4dc \ub514\uc790\uc778 \uac1c\uc120**:\\n    `Projects` \ud398\uc774\uc9c0\uc758 \uce74\ub4dc \ub808\uc774\uc544\uc6c3\uacfc \uc774\ubbf8\uc9c0 \ud45c\uc2dc \ubc29\uc2dd\uc744 \ub300\ud3ed \uac1c\uc120\ud558\uc5ec \uc2dc\uac01\uc801 \uc77c\uad00\uc131\uacfc \uc548\uc815\uac10\uc744 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.\\n    *   **\uc77c\uad00\ub41c \uce74\ub4dc \ube44\uc728**: \uac01 \ud504\ub85c\uc81d\ud2b8 \uce74\ub4dc\uc758 \uc774\ubbf8\uc9c0 \uc601\uc5ed\uacfc \ud558\ub2e8\uc758 \uc81c\ubaa9/\uc124\uba85 \uc601\uc5ed\uc774 \ud56d\uc0c1 \ub3d9\uc77c\ud55c \ube44\uc728\uc744 \uc720\uc9c0\ud558\ub3c4\ub85d \uc218\uc815\ud588\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uc774\ubbf8\uc9c0 \ud06c\uae30\uc5d0 \ub530\ub77c \uce74\ub4dc \uc804\uccb4 \uad6c\uc870\uac00 \ud754\ub4e4\ub9ac\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n    *   **\uc774\ubbf8\uc9c0 \uc2a4\ud0c0\uc77c\ub9c1 \uac1c\uc120**: \uc774\ubbf8\uc9c0\uac00 \uc798\ub9ac\uc9c0 \uc54a\uace0 \uc6d0\ubcf8 \uac00\ub85c\uc138\ub85c \ube44\uc728\uc744 \uc720\uc9c0\ud558\uba74\uc11c, \uce74\ub4dc \uc601\uc5ed \ub0b4\uc5d0\uc11c \uc911\uc559\uc5d0 \uc704\uce58\ud558\ub3c4\ub85d \ubcc0\uacbd\ud588\uc2b5\ub2c8\ub2e4. \uc774\ub85c \uc778\ud574 \ud06c\uae30\uac00 \uc791\uc740 \uc774\ubbf8\uc9c0\ub3c4 \uc5b4\uc0c9\ud568 \uc5c6\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc785\ub2c8\ub2e4.\\n\\n3.  **Awards \ud398\uc774\uc9c0 \uce90\ub7ec\uc140 \uae30\ub2a5 \ucd94\uac00**:\\n    `Awards` \ud398\uc774\uc9c0\ub97c \ub300\ub300\uc801\uc73c\ub85c \uac1c\ud3b8\ud558\uc5ec \ud558\ub098\uc758 \uc218\uc0c1 \ub0b4\uc5ed\uc5d0 \uc5ec\ub7ec \uc0ac\uc9c4\uc744 \ubcf4\uc5ec\uc904 \uc218 \uc788\ub294 \uc774\ubbf8\uc9c0 \uce90\ub7ec\uc140\uc744 \ub3c4\uc785\ud588\uc2b5\ub2c8\ub2e4.\\n    *   **\ub2e4\uc911 \uc774\ubbf8\uc9c0 \uc9c0\uc6d0**: \uc774\uc81c \ud558\ub098\uc758 \uce74\ub4dc\uc5d0 \uc5ec\ub7ec \uc7a5\uc758 \uc0ac\uc9c4\uc744 \ud3ec\ud568\ud558\uace0 \ub118\uaca8\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n    *   **\uc778\ud130\ub799\ud2f0\ube0c UI**: \ub9c8\uc6b0\uc2a4\ub97c \uc62c\ub9ac\uba74 \ub098\ud0c0\ub098\ub294 \uc88c\uc6b0 \ud0d0\uc0c9 \ubc84\ud2bc\uacfc \ud558\ub2e8\uc758 \uc778\ub514\ucf00\uc774\ud130(\uc810)\ub97c \ud1b5\ud574 \uc9c1\uad00\uc801\uc73c\ub85c \uc774\ubbf8\uc9c0\ub97c \ud0d0\uc0c9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n    *   **\uc790\ub3d9 \uc7ac\uc0dd \uae30\ub2a5**: \uc0ac\uc6a9\uc790\uac00 \ubcc4\ub3c4\ub85c \uc870\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc77c\uc815 \uc2dc\uac04\ub9c8\ub2e4 \uc0ac\uc9c4\uc774 \uc790\ub3d9\uc73c\ub85c \uc804\ud658\ub418\uc5b4 \ub3d9\uc801\uc778 \ub290\ub08c\uc744 \uc90d\ub2c8\ub2e4.\\n    *   **\ub514\uc790\uc778 \uac1c\uc120**: \uc774\ubbf8\uc9c0 \ubaa8\uc11c\ub9ac\ub97c \ub465\uae00\uac8c \ucc98\ub9ac\ud558\uc5ec \uc804\uccb4\uc801\uc778 \ub514\uc790\uc778\uacfc \uc870\ud654\ub97c \uc774\ub8e8\ub3c4\ub85d \ud558\uace0, \ubd80\ub4dc\ub7ec\uc6b4 \uc778\uc0c1\uc744 \uc8fc\ub3c4\ub85d \uac1c\uc120\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ubc88 \uac1c\uc120 \uc791\uc5c5\ub4e4\uc744 \ud1b5\ud574 \uc6f9\uc0ac\uc774\ud2b8\ub97c \ub458\ub7ec\ubcf4\ub294 \uacbd\ud5d8\uc774 \ub354 \ucf8c\uc801\ud574\uc84c\uae30\ub97c \ubc14\ub78d\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub3c4 \uc0ac\uc6a9\uc131\uacfc \ub514\uc790\uc778\uc744 \uafb8\uc900\ud788 \ub2e4\ub4ec\uc5b4 \ub098\uac00\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n\uac10\uc0ac\ud569\ub2c8\ub2e4!"},{"id":"website-renewal","metadata":{"permalink":"/blog/website-renewal","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-01-17-website-renewal.md","source":"@site/blog/2026-01-17-website-renewal.md","title":"\uc6f9\uc0ac\uc774\ud2b8 \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d","description":"\uc548\ub155\ud558\uc138\uc694! \uc624\ub298\uc740 \uc81c \uac1c\uc778 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc6f9\uc0ac\uc774\ud2b8\uc5d0 \ub300\ud55c \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d\uc744 \uacf5\uc720\ud558\ub824 \ud569\ub2c8\ub2e4.","date":"2026-01-17T00:00:00.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"renewal","permalink":"/blog/tags/renewal"},{"inline":true,"label":"portfolio","permalink":"/blog/tags/portfolio"},{"inline":true,"label":"web-dev","permalink":"/blog/tags/web-dev"}],"readingTime":1.02,"hasTruncateMarker":true,"authors":[{"name":"Paul Seo","title":"Robotics Software Engineer, Hyundai-WIA","url":"http://linkedin.com/in/paulusseo/","page":{"permalink":"/blog/authors/paulus-seo"},"socials":{"github":"https://github.com/paulus-seo","linkedin":"https://www.linkedin.com/in/paulusseo/"},"imageURL":"https://github.com/paulus-seo.png","key":"paulus-seo"}],"frontMatter":{"slug":"website-renewal","title":"\uc6f9\uc0ac\uc774\ud2b8 \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d","authors":["paulus-seo"],"tags":["docusaurus","renewal","portfolio","web-dev"]},"unlisted":false,"prevItem":{"title":"\uc6f9\uc0ac\uc774\ud2b8 \uae30\ub2a5 \uac1c\uc120 \uae30\ub85d (2)","permalink":"/blog/website-improvements-part-2"}},"content":"\uc548\ub155\ud558\uc138\uc694! \uc624\ub298\uc740 \uc81c \uac1c\uc778 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc6f9\uc0ac\uc774\ud2b8\uc5d0 \ub300\ud55c \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d\uc744 \uacf5\uc720\ud558\ub824 \ud569\ub2c8\ub2e4.\\nDocusaurus \uae30\ubc18\uc73c\ub85c \uad6c\ucd95\ub41c \uc774 \uc6f9\uc0ac\uc774\ud2b8\ub294 \ubc29\ubb38\uc790\ub4e4\uc5d0\uac8c \uc800\uc758 \uacbd\ud5d8\uacfc \ud504\ub85c\uc81d\ud2b8\ub97c \ubcf4\ub2e4 \ud6a8\uacfc\uc801\uc73c\ub85c \uc804\ub2ec\ud558\uae30 \uc704\ud574 \uc5ec\ub7ec \ud398\uc774\uc9c0\uac00 \uac1c\uc120\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n**\uc8fc\uc694 \ub9ac\ub274\uc5bc \ub0b4\uc6a9:**\\n\\n1.  **Awards \ud398\uc774\uc9c0 \ucd94\uac00**: \uc800\uc758 \uc218\uc0c1 \uc774\ub825\uc744 \ud55c\ub208\uc5d0 \ubcfc \uc218 \uc788\ub294 `Awards` \ud398\uc774\uc9c0\ub97c \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\uc874 \ud504\ub85c\uc81d\ud2b8 \ud398\uc774\uc9c0\uc640 \uc720\uc0ac\ud55c \uce74\ub4dc\ud615 \ub808\uc774\uc544\uc6c3\uc73c\ub85c \uc77c\uad00\uc131\uc744 \uc720\uc9c0\ud588\uc2b5\ub2c8\ub2e4.\\n2.  **Projects \ud398\uc774\uc9c0 \uac1c\uc120**: \uae30\uc874\uc758 \uac04\ub2e8\ud55c `Projects` \ud398\uc774\uc9c0\ub97c \ub2e4\uc591\ud55c \uc800\uc758 \ud504\ub85c\uc81d\ud2b8\ub4e4\uc744 \uce74\ub4dc \ud615\ud0dc\ub85c \ubcf4\uc5ec\uc8fc\ub294 \uac24\ub7ec\ub9ac \ud615\ud0dc\ub85c \uc5c5\ub370\uc774\ud2b8\ud588\uc2b5\ub2c8\ub2e4. \uac01 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ub300\ud55c \uc124\uba85\uacfc \uc774\ubbf8\uc9c0\ub97c \ud1b5\ud574 \uc27d\uac8c \ub0b4\uc6a9\uc744 \ud30c\uc545\ud560 \uc218 \uc788\ub3c4\ub85d \ud588\uc2b5\ub2c8\ub2e4.\\n3.  **About \ud398\uc774\uc9c0 \ud0c0\uc784\ub77c\uc778 \uac1c\ud3b8**: \uac00\uc7a5 \ud070 \ubcc0\ud654\ub294 `About` \ud398\uc774\uc9c0\uc785\ub2c8\ub2e4. \uc800\uc758 \ud559\ub825 \ubc0f \uacbd\ub825 \uc0ac\ud56d\uc744 LinkedIn \uc2a4\ud0c0\uc77c\uc758 \ud0c0\uc784\ub77c\uc778\uc73c\ub85c \uc7ac\uad6c\uc131\ud588\uc2b5\ub2c8\ub2e4.\\n    *   **\uacc4\uce35\uc801 \uad6c\uc870**: \uac01 \uae30\uad00/\ud68c\uc0ac\ubcc4\ub85c \uadf8\ub8f9\ud654\ud558\uc5ec, \uadf8\ub8f9 \ud5e4\ub354(\ub300\ud45c \ub85c\uace0 \ubc0f \uc774\ub984) \uc544\ub798\uc5d0 \ud574\ub2f9 \uae30\uad00/\ud68c\uc0ac\uc5d0\uc11c\uc758 \ud65c\ub3d9\ub4e4\uc744 \uc2dc\uac04\uc21c\uc73c\ub85c \ub098\uc5f4\ud588\uc2b5\ub2c8\ub2e4.\\n    *   **\ub300\ud45c \ub85c\uace0 \ubc0f \uc11c\ube0c \ub85c\uace0 \ubd84\ub9ac**: \uac01 \uadf8\ub8f9\uc740 \ub300\ud45c \ub85c\uace0\ub97c \uac00\uc9c0\uba70, \uadf8\ub8f9 \ub0b4 \uac1c\ubcc4 \ud65c\ub3d9(\ud559\uc704, \uc9c1\ucc45 \ub4f1) \ub610\ud55c \ubcc4\ub3c4\uc758 \ub85c\uace0\ub97c \uac00\uc9c8 \uc218 \uc788\ub3c4\ub85d \ud558\uc5ec \uc2dc\uc778\uc131\uc744 \ub192\uc600\uc2b5\ub2c8\ub2e4.\\n    *   **\ud638\ubc84 \ud6a8\uacfc**: \uac01 `groupItem` \uce74\ub4dc\uc5d0 \ub9c8\uc6b0\uc2a4\ub97c \uc62c\ub9ac\uba74 \uc0b4\uc9dd \ud280\uc5b4\ub098\uc624\ub294 \ub4ef\ud55c \uc2dc\uac01\uc801 \ud6a8\uacfc\ub97c \ucd94\uac00\ud558\uc5ec \uc778\ud130\ub799\ud2f0\ube0c\ud55c \uacbd\ud5d8\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n    *   **\ub514\uc790\uc778 \uac1c\uc120**: \ub85c\uace0 \ud14c\ub450\ub9ac \uc644\ud654 \ubc0f `groupHeader`\uc640 \uccab \ubc88\uc9f8 `groupItem` \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc870\uc808\ud558\uc5ec \uc804\uccb4\uc801\uc778 \ub514\uc790\uc778\uc774 \ub354\uc6b1 \uc790\uc5f0\uc2a4\ub7fd\uace0 \uae54\ub054\ud558\uac8c \ubcf4\uc774\ub3c4\ub85d \uac1c\uc120\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ubc88 \ub9ac\ub274\uc5bc\uc744 \ud1b5\ud574 \uc800\uc758 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc6f9\uc0ac\uc774\ud2b8\uac00 \ub354\uc6b1 \uc804\ubb38\uc801\uc774\uace0 \uc0ac\uc6a9\uc790 \uce5c\ud654\uc801\uc73c\ub85c \ubc14\ub00c\uc5c8\uae30\ub97c \uae30\ub300\ud569\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub3c4 \uafb8\uc900\ud788 \ub0b4\uc6a9\uc744 \uc5c5\ub370\uc774\ud2b8\ud558\uace0 \ubc1c\uc804\uc2dc\ucf1c \ub098\uac00\uaca0\uc2b5\ub2c8\ub2e4.\\n\uac10\uc0ac\ud569\ub2c8\ub2e4!"}]}}')}}]);